#!/usr/bin/env python3
"""Regenerate the checked-in C font from the adjacent, OFL-licensed TTF."""
from pathlib import Path
root = Path(__file__).resolve().parent
data = (root / 'SpaceMono-Regular.ttf').read_bytes()
with (root / 'remote_svg_font.inc').open('w') as out:
    out.write('/* Space Mono Regular; see LICENSE-SpaceMono.txt. Generated by embed_font.py. */\n')
    out.write('static const unsigned char remote_svg_font[] = {\n')
    for i in range(0, len(data), 16):
        out.write('    ' + ','.join(f'0x{v:02x}' for v in data[i:i+16]) + ',\n')
    out.write('};\n')
